mapper.select:
select id, is_deleted, nezha_tenant_code, definition_id, definition_version, skill_id, artifact_path, artifact_checksum, publisher_type, publish_status, error_msg, create_at, create_by, create_name, update_at, update_by, update_name from agent_publish_record where is_deleted = 0
and definition_id = #{definitionId,jdbcType=BIGINT}
and publish_status = #{publishStatus,jdbcType=VARCHAR}
order by id desc
